    elementos: [{ texto: 'Hongos que descomponen la hojarasca', categoria: 0 }, { texto: 'Ardillas que dispersan bellotas', categoria: 0 }, { texto: 'Bacterias fijadoras de nitrógeno del suelo', categoria: 0 }, { texto: 'Temperatura media del invierno', categoria: 1 }, { texto: 'pH del suelo', categoria: 1 }, { texto: 'Horas de luz solar al día', categoria: 1 }],
